    let rx: f32 = pc.x * cy + pc.z * sy;
    let rz1: f32 = -pc.x * sy + pc.z * cy;
    let ry: f32 = pc.y * cp - rz1 * sp;
    let rz: f32 = pc.y * sp + rz1 * cp;
